import{_ as t,o as a,c as s,ag as o}from"./chunks/framework.DNmTgtHf.js";const u=JSON.parse('{"title":"Abstract Class vs. Interface — the decision","description":"","frontmatter":{},"headers":[],"relativePath":"java/foundations/abstract_class_vs_interface/AbstractClassVsInterface.md","filePath":"java/foundations/abstract_class_vs_interface/AbstractClassVsInterface.md"}'),i={name:"java/foundations/abstract_class_vs_interface/AbstractClassVsInterface.md"};function n(r,e,c,l,d,h){return a(),s("div",null,[...e[0]||(e[0]=[o(`<h1 id="abstract-class-vs-interface-—-the-decision" tabindex="-1">Abstract Class vs. Interface — the decision <a class="header-anchor" href="#abstract-class-vs-interface-—-the-decision" aria-label="Permalink to &quot;Abstract Class vs. Interface — the decision&quot;">​</a></h1><blockquote><p>The most common &quot;which should I use?&quot; question in Java. Both express abstraction, but with different powers and limits.</p></blockquote><hr><h2 id="feature-comparison" tabindex="-1">Feature comparison <a class="header-anchor" href="#feature-comparison" aria-label="Permalink to &quot;Feature comparison&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Feature</th><th>Abstract class</th><th>Interface</th></tr></thead><tbody><tr><td>Instance fields (state)</td><td>✅ Yes</td><td>❌ No (only <code>public static final</code> constants)</td></tr><tr><td>Constructors</td><td>✅ Yes</td><td>❌ No</td></tr><tr><td><code>protected</code> / package-private members</td><td>✅ Yes</td><td>❌ No — everything is effectively <code>public</code></td></tr><tr><td>Method bodies (implementation)</td><td>✅ Yes (regular + abstract)</td><td>✅ Yes — via <code>default</code> and <code>static</code> methods (Java 8+)</td></tr><tr><td>Can a class have more than one?</td><td>❌ Only one parent class (single inheritance)</td><td>✅ A class can implement many interfaces</td></tr><tr><td>Static-initializer blocks</td><td>✅ Yes</td><td>❌ No</td></tr><tr><td>Ideal conceptual role</td><td>Says <em>what a thing IS</em> (Dog <strong>is an</strong> Animal)</td><td>Says <em>what a thing CAN DO</em> (Dog <strong>can</strong> Bark)</td></tr></tbody></table><hr><h2 id="when-to-reach-for-each" tabindex="-1">When to reach for each <a class="header-anchor" href="#when-to-reach-for-each" aria-label="Permalink to &quot;When to reach for each&quot;">​</a></h2><p><strong>Use an abstract class when:</strong></p><ul><li>You need shared <strong>instance state</strong> (fields) across all subclasses.</li><li>You need a <strong>constructor</strong> to enforce invariants (&quot;you can&#39;t construct me without X&quot;).</li><li>You need <strong><code>protected</code></strong> members that subclasses can touch but outsiders cannot.</li><li>There is genuine &quot;IS-A&quot; taxonomy (e.g., <code>Shape</code> → <code>Circle</code> / <code>Square</code>).</li><li>You want a <strong>template method</strong> — a concrete method in the parent that calls abstract hook methods in the subclass (this is the GoF Factory Method&#39;s whole point).</li></ul><p><strong>Use an interface when:</strong></p><ul><li>You only want to describe a <strong>capability</strong> or <strong>contract</strong>, not a taxonomy.</li><li>The same capability cuts across unrelated class hierarchies (e.g., <code>Comparable</code>, <code>Serializable</code>).</li><li>You want a type that a class can implement <strong>alongside</strong> extending some other class.</li><li>You have no state or constructor requirements.</li></ul><hr><h2 id="default-methods-—-a-nuance" tabindex="-1">Default methods — a nuance <a class="header-anchor" href="#default-methods-—-a-nuance" aria-label="Permalink to &quot;Default methods — a nuance&quot;">​</a></h2><p>Since Java 8, interfaces can have <code>default</code> and <code>static</code> methods. This blurs the line but does <strong>not</strong> eliminate it:</p><ul><li><code>default</code> methods still have no access to instance fields (there are none) or <code>protected</code> members.</li><li>You cannot force construction through a constructor.</li><li>You can still implement the interface in multiple classes simultaneously.</li><li><code>default</code> methods cannot be <code>final</code> — implementers can always override them.</li></ul><p>Use default methods for convenience implementations on top of a small set of truly abstract methods — not to smuggle state-like behavior into an interface.</p><hr><h2 id="template-method-—-the-named-gof-pattern" tabindex="-1">Template Method — the named GoF pattern <a class="header-anchor" href="#template-method-—-the-named-gof-pattern" aria-label="Permalink to &quot;Template Method — the named GoF pattern&quot;">​</a></h2><p>A <strong>template method</strong> is a <code>final</code> concrete method on an abstract class that calls <code>abstract</code> hook methods that subclasses fill in. The parent owns the algorithm; the children only customise the steps that vary.</p><div class="language-java vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">java</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">public</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> abstract</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> class</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> DeveloperHiringProcess</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> {</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">    public</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> final</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> Employee </span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">onboard</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">() {        </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// ← template (final, can&#39;t be replaced)</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">        checkBudget</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">();</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">        Employee e </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> createDeveloper</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">();      </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// ← hook (abstract, child fills in)</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">        provisionLaptop</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(e);</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">        return</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> e;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    }</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">    protected</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> abstract</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> Employee </span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">createDeveloper</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">();   </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// ← hook</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">    private</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> void</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> checkBudget</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">() { ... }               </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// ← internal step, hidden</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">    private</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> void</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> provisionLaptop</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(Employee </span><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">e</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">) { ... } </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// ← internal step, hidden</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><p>This is why Factory Method uses an abstract class, not an interface. An interface cannot:</p><ul><li>Mark a <code>default</code> method <code>final</code> (so the algorithm could be replaced)</li><li>Hold private fields for shared state</li><li>Use <code>protected</code> to expose hooks to subclasses without making them public</li></ul><p>Template Method is named in the GoF Behavioural section, but you&#39;ve already been writing it whenever you used Factory Method.</p><hr><h2 id="rule-of-thumb" tabindex="-1">Rule of thumb <a class="header-anchor" href="#rule-of-thumb" aria-label="Permalink to &quot;Rule of thumb&quot;">​</a></h2><ul><li><strong>Start with an interface.</strong> If you later need state, a constructor, a <code>protected</code> member, or a <code>final</code> method, promote to an abstract class.</li><li>When you see an abstract class in a GoF pattern (like Factory Method&#39;s <code>DeveloperHiringProcess</code>), it&#39;s usually because the parent wants a <strong>template method</strong> plus shared state — things an interface cannot do cleanly.</li><li>Don&#39;t avoid one in favor of the other dogmatically; each exists for different jobs.</li></ul><hr><h2 id="four-decision-questions" tabindex="-1">Four decision questions <a class="header-anchor" href="#four-decision-questions" aria-label="Permalink to &quot;Four decision questions&quot;">​</a></h2><p>Run through these in order:</p><ol><li><strong>Does this thing need state across implementations?</strong> Yes → abstract class. No → prefer interface.</li><li><strong>Is it a &quot;what kind of object am I&quot; claim</strong> (taxonomy / IS-A) <strong>or a &quot;what can this object do&quot; claim</strong> (capability)? Taxonomy → abstract class. Capability → interface.</li><li><strong>Could the same capability appear on completely unrelated hierarchies?</strong> Yes (<code>Comparable</code>, <code>Serializable</code>) → interface. No (a <code>Shape</code> parent for <code>Circle</code> / <code>Square</code>) → abstract class.</li><li><strong>Do I need a template method that calls subclass-specific hooks?</strong> Yes → abstract class — interfaces have <code>default</code> methods but no <code>final</code>, so you can&#39;t lock the algorithm.</li></ol><hr><h2 id="practice-exercises" tabindex="-1">Practice exercises <a class="header-anchor" href="#practice-exercises" aria-label="Permalink to &quot;Practice exercises&quot;">​</a></h2><p>Each takes 15–30 minutes:</p><ul><li>[ ] <strong>Abstract Factory variation: factory base class.</strong> In <code>creational/abstract_factory/</code>, introduce an <code>AbstractFurnitureFactory</code> abstract class that <code>CheapFurnitureFactory</code> and <code>LuxuryFurnitureFactory</code> extend. Give it a <code>final</code> template method <code>deliverSet()</code> that calls <code>createChair()</code> + <code>createSofa()</code> and prints a delivery summary. Compare against the current &quot;static helper on the runner&quot; approach. Which feels more natural for <em>this</em> domain? When would you flip the choice?</li><li>[ ] <strong>Strategy pattern in two flavours.</strong> Write a tiny Strategy example (e.g., <code>PaymentStrategy</code> with <code>CardPayment</code> / <code>CashPayment</code> / <code>UpiPayment</code>) once with <code>interface PaymentStrategy</code> and once with <code>abstract class PaymentStrategy</code>. Note where each adds value (interface — clean substitution; abstract class — shared logging or audit hooks). Does it match your answer to question #1?</li><li>[ ] <strong><code>default</code> methods test.</strong> Take any interface in this repo and add a <code>default</code> method that depends on the abstract methods. Implement it across two classes — does the default work? When would you instead promote to abstract class?</li><li>[ ] <strong>Builder hierarchy (EJ Item 2 advanced).</strong> Outside this repo: read EJ Item 2&#39;s <code>Pizza</code> / <code>NyPizza</code> / <code>Calzone</code> example. The <code>Pizza</code> parent is <strong>abstract class</strong>, not interface — why? Tie back to question #1 (state) and question #4 (template method). This also explains why some Builder products in production code are <code>abstract</code>, not <code>final</code>.</li></ul><hr><h2 id="where-the-decision-came-up-in-this-repo" tabindex="-1">Where the decision came up in this repo <a class="header-anchor" href="#where-the-decision-came-up-in-this-repo" aria-label="Permalink to &quot;Where the decision came up in this repo&quot;">​</a></h2><ul><li><strong>Abstract Factory:</strong> &quot;should <code>furnishRoom</code> go on <code>FurnitureSetFactory</code> (interface, default method) or stay on the runner side?&quot; — see <code>creational/abstract_factory/</code>. Answer: keep it on the caller because consumption isn&#39;t the factory&#39;s responsibility — but a <code>default</code> method <em>would</em> have worked technically.</li><li><strong>Factory Method:</strong> <code>DeveloperHiringProcess</code> is an abstract class because it holds <code>private final</code> services and a <code>final onboard()</code> template method. An interface couldn&#39;t express either.</li><li><strong>Builder (GoF Director):</strong> <code>OfferConstructionSteps</code> is a pure interface with no state; the concrete builders hold their own state. The steps are a <em>capability</em> every builder shares; per-builder state is per-builder, not per-step-interface.</li></ul><hr><h2 id="quick-recall" tabindex="-1">Quick recall <a class="header-anchor" href="#quick-recall" aria-label="Permalink to &quot;Quick recall&quot;">​</a></h2><p><strong>Q. Three things an abstract class can do that an interface cannot (cleanly)?</strong> A. Hold instance state, enforce construction through a constructor, and mark methods <code>final</code> to lock the algorithm. Interfaces have <code>default</code> methods but no instance fields, no constructors, and no way to forbid override.</p><p><strong>Q. Rule-of-thumb starting point?</strong> A. Start with an interface. Promote to an abstract class only when you actually need state, a constructor, <code>protected</code> visibility, or a <code>final</code> method.</p><p><strong>Q. Why is <code>DeveloperHiringProcess</code> an abstract class rather than an interface?</strong> A. It holds <code>private final</code> services as shared state and a <code>final onboard()</code> template method that calls the abstract <code>createDeveloper()</code> hook. An interface can&#39;t hold instance state and can&#39;t mark <code>default</code> methods <code>final</code> — both load-bearing for this design.</p><p><strong>Q. Multiple inheritance — what does Java allow?</strong> A. One <code>extends</code> (single class inheritance), many <code>implements</code> (multiple interface implementation). Abstract classes inherit the single-class limit; interfaces don&#39;t.</p><p><strong>Q. What does a <code>default</code> method on an interface specifically <em>not</em> give you?</strong> A. No access to instance state (there is none), no <code>final</code>, no <code>protected</code> visibility — and implementers can always override. It&#39;s a convenience layer, not a replacement for abstract-class capability.</p><p><strong>Q. The four decision questions in order?</strong> A. (1) Need state across implementations? (2) Taxonomy or capability? (3) Could the capability cut across unrelated hierarchies? (4) Need a template method with locked algorithm? Two or more &quot;yes / capability&quot; answers → interface; otherwise abstract class.</p><hr><h2 id="related-topics" tabindex="-1">Related topics <a class="header-anchor" href="#related-topics" aria-label="Permalink to &quot;Related topics&quot;">​</a></h2><ul><li><strong>Access Modifiers Deep Dive</strong> — explains <em>why</em> the modifiers chosen for <code>DeveloperHiringProcess</code> (protected ctor, public final, protected abstract, private helpers) only work in an abstract class.</li><li><strong>Inheritance</strong> — covers <code>extends</code> mechanics that abstract classes use; interfaces use <code>implements</code>.</li></ul>`,48)])])}const m=t(i,[["render",n]]);export{u as __pageData,m as default};
